@register.simple_tag
def icon(name: str, classes: str = "h-4 w-4") -> str:
    body = PATHS.get(name, "")
    return mark_safe(
        '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" '
        'stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" '
        f'aria-hidden="true" class="lucide lucide-{escape(name)} {escape(classes)}">{body}</svg>'
    )
